 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    background = grid[0][0]
    # Continue each diagonal same-color segment. The continuation reaches the
    # first occupied cell (replacing it), then stops; otherwise it reaches edge.
    for color in range(10):
        if color == background:
            continue
        cells = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == color}
        for r, c in cells:
            for dr, dc in ((1, 1), (1, -1)):
                r2, c2 = r + dr, c + dc
                if (r2, c2) not in cells or (r2 + dr, c2 + dc) in cells:
                    continue
                rr, cc = r2 + dr, c2 + dc
                while 0 <= rr < h and 0 <= cc < w:
                    occupied = grid[rr][cc] != background
                    out[rr][cc] = color
                    if occupied:
                        break
                    rr += dr
                    cc += dc
    return out

